INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'la-geometria-espacial-colectiva', 'La Geometría Espacial Colectiva', 'Dinámica de construcción kinésica y rompecabezas humano donde las patrullas coordinan sus cuerpos para formar figuras geométricas en el espacio.', '<h2>📜 Descripción de La Geometría Espacial Colectiva</h2>
<p><b>La Geometría Espacial Colectiva</b> es una dinámica scout de alineación corporal, trabajo en equipo y percepción tridimensional. Organizados en patrullas o seisenas en el patio o campo abierto, los participantes deben responder al llamado del animador que solicita la construcción de figuras geométricas tridimensionales complejas (ej. <i>''Un Triángulo Isósceles''</i>, <i>''Una Estrella de 5 Puntas''</i> o <i>''Una Pirámide Truncada''</i>). Utilizando únicamente sus cuerpos entrelazados, brazos y piernas, los scouts deben arrodillarse, acostarse o erguirse en perfecta sincronía hasta moldear la figura solicitada en el menor tiempo posible.</p>
<p>Esta actividad ejercita la visión espacial, el liderazgo situacional y la coordinación colectiva en Manada, Compañía y Tropa.</p>

<h2>🎲 ¿Cómo se juega La Geometría Espacial Colectiva?</h2>
<p>Para llevar a cabo la dinámica con solemnidad y orden, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Ubicación de Equipos:</b> Se forman las patrullas en círculos independientes en el centro del salón o prado.</li>
  <li><b>Llamado de la Figura:</b> El dirigente nombra una figura geométrica o símbolo (ej. <i>''¡Círculo Concentrico con Cruz Interna!''</i>).</li>
  <li><b>Coordinación Táctica:</b> Al silbato, el guía de patrulla distribuye a los beneficiarios para formar los vértices, lados y diagonales con sus cuerpos.</li>
  <li><b>Fijación de la Forma:</b> El equipo sostiene la posición sin perder la estructura durante 5 segundos para la inspección del dirigente.</li>
  <li><b>Complejidad Creciente:</b> Se suceden rondas aumentando la dificultad mediante figuras en movimiento o con ojos vendados.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de La Geometría Espacial Colectiva</h2>
<p>La actividad valora la precisión espacial y el trabajo en equipo en el Tally:</p>
<ul>
  <li><b>Mayor Perfección Geométrica:</b> Otorgar 5 puntos a la patrulla que modele los lados y ángulos con mayor simetría.</li>
  <li><b>Velocidad de Ensamblaje:</b> Otorgar 3 puntos al equipo que logre armar la figura en el menor tiempo.</li>
  <li><b>Cooperación Total:</b> Otorgar 3 puntos al grupo que integre armónicamente a todos sus miembros sin excepción.</li>
</ul>', '/uploads/la-geometria-espacial-colectiva.webp', 'publicado', '{"areas": ["creatividad", "corporalidad"], "unidades": ["manada", "compañía", "tropa"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Ninguno"], "objetivos": ["Estimular la creatividad", "Reforzar la coordinación al interior del equipo", "Estimular la agilidad mental", "Crear un clima de pertenencia"], "justificacion_areas": "La Geometría Espacial Colectiva potencia la creatividad al requerir la resolución ingeniosa de rompecabezas anatómicos en 3D. Desarrolla la corporalidad al ejercitar la propiocepción, la elasticidad, el equilibrio postural y la coordinación kinésica entre pares.", "variaciones": "<b>Geometría Espacial a Oscuras:</b> Armar las figuras en silencio utilizando únicamente el tacto en el piso de campamento.<br><b>Geometría Dinámica:</b> Las figuras deben desplazarse 5 metros en el plano sin deformar los lados geométricos.<br><b>Símbolos Scouts en 3D:</b> Formar la Flor de Lis o el Trébol WAGGGS con la totalidad de la unidad.", "recomendaciones": "Revisar que la superficie esté despejada. Fomentar la comunicación tranquila y la distribución eficiente del espacio entre seisenas.", "objetivos_educativos": [{"id": "ec280dd0-2d80-4b84-86ad-2d362da14886", "area": "Creatividad", "unidad": "Manada", "texto": "Me gusta participar en juegos de observación.", "como_se_cumple": "Observando el plano espacial para acomodar el cuerpo en la posición geométrica requerida."}, {"id": "dcdcce42-6b31-45f7-a135-290f0f74b5a6", "area": "Creatividad", "unidad": "Manada", "texto": "Me gustan los juegos en que tengo que usar mi agilidad mental.", "como_se_cumple": "Resolviendo velozmente la distribución de vértices y lados en el equipo."}, {"id": "e1b7276f-4fd2-4c39-a32a-bd7fadbee702", "area": "Creatividad", "unidad": "Compañía", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Proponiendo soluciones tácticas para armar los ángulos de la figura."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "unidad": "Compañía", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Visualizando el resultado geométrico desde la perspectiva del observador externo."}, {"id": "49ae6ac6-be8f-4f2c-8b3e-6711d041181f", "area": "Creatividad", "unidad": "Tropa", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Coordinando con dinamismo las posiciones espaciales de la patrulla."}, {"id": "3d0dff9b-11cd-4a30-b3a6-ec011ad95062", "area": "Creatividad", "unidad": "Tropa", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Sintetizando abstracciones tridimensionales mediante el alineamiento corporal."}, {"id": "d9ebcd96-c9cf-444f-94fb-5569110a1b99", "area": "Corporalidad", "unidad": "Manada", "texto": "Participo en actividades que me ayudan a tener un cuerpo cada vez más fuerte, ágil, veloz y flexible.", "como_se_cumple": "Estirando y flexionando extremidades para moldear las líneas de la figura geométrica."}, {"id": "626a313e-0407-4cfd-b714-c6aa6e51738c", "area": "Corporalidad", "unidad": "Manada", "texto": "Manejo cada vez mejor mis brazos, piernas, manos y pies.", "como_se_cumple": "Afinando la postura de brazos y piernas para mantener la figura estable."}, {"id": "273f60b8-7953-4416-97c3-e8c83615364f", "area": "Corporalidad", "unidad": "Compañía", "texto": "Participo en actividades que me ayudan a mantener mi cuerpo fuerte y sano.", "como_se_cumple": "Ejercitando el equilibrio tónico y la resistencia en alineaciones grupales."}, {"id": "91473f71-9345-4bcf-bfc7-dea709d12361", "area": "Corporalidad", "unidad": "Compañía", "texto": "Respeto mi cuerpo y el de los demás.", "como_se_cumple": "Respetando la postura y límites físicos de las compañeras al entrelazar brazos."}, {"id": "5c9843d1-39fd-4298-870c-5e46f29ffbf6", "area": "Corporalidad", "unidad": "Tropa", "texto": "Participo en actividades que me ayudan a mantener mi cuerpo fuerte y sano.", "como_se_cumple": "Perfeccionando el control psicomotriz y la postura en equipo."}, {"id": "fb56310a-a9cf-46e3-9c34-c4643f6b9035", "area": "Corporalidad", "unidad": "Tropa", "texto": "Respeto mi cuerpo y el de los demás.", "como_se_cumple": "Fomentando el cuidado y la alineación armónica del grupo en el espacio."}]}'::jsonb, NOW(), NOW(), NULL, NULL
